package es.aelb.backendweb.infrastructure.email;
import es.aelb.backendweb.application.email.*; import es.aelb.backendweb.infrastructure.config.EmailProperties; import org.springframework.stereotype.Component; import org.springframework.context.annotation.Profile; import software.amazon.awssdk.services.ses.SesClient; import software.amazon.awssdk.services.ses.model.*;
@Component("sesEmailSender") @Profile("prod")
public class SesEmailSender implements EmailSender {
 private final SesClient ses; private final EmailProperties props;
 public SesEmailSender(EmailProperties props){this.props=props; if("local".equalsIgnoreCase(props.getAppEnv())||!"ses".equalsIgnoreCase(props.getProvider())) throw new IllegalStateException("SES no puede inicializarse en entorno local/no SES"); this.ses=SesClient.builder().region(software.amazon.awssdk.regions.Region.of(props.getAwsRegion())).build();}
 public void send(EmailMessage m){try{ses.sendEmail(SendEmailRequest.builder().source(props.getFrom()).destination(Destination.builder().toAddresses(m.recipient()).build()).message(Message.builder().subject(Content.builder().data(m.subject()).charset("UTF-8").build()).body(Body.builder().text(Content.builder().data(m.plainText()).charset("UTF-8").build()).html(Content.builder().data(m.html()).charset("UTF-8").build()).build()).build()).build());}catch(SesException e){int status=e.statusCode(); if(status==400 && e.awsErrorDetails()!=null && String.valueOf(e.awsErrorDetails().errorCode()).toLowerCase().contains("throttl")) throw new TemporaryEmailException("SES throttling",e); if(status>=500)throw new TemporaryEmailException("SES temporalmente no disponible",e); throw new PermanentEmailException("SES rechazó el email",e);}catch(RuntimeException e){throw new TemporaryEmailException("Error de red con SES",e);}}
}
